   "source": [
    "col_names <- colnames(df)\n",
    "new_data <- list()\n",
    "for (i in 1:length(col_names)) {\n",
    "    e <- col_names[i]\n",
    "    if (class(e) == \"character\") {\n",
    "        if (substr(e, 1, 1) == \"X\") {\n",
    "            num <- substr(e, 2, nchar(e))\n",
    "            new_data[i] <- as.numeric(num)\n",
    "        } else {\n",
    "            new_data[i] <- e\n",
    "        }\n",
    "    }\n",
    "}\n",
    "df <- rbind(df, new_data)"
   ]
  },
