   "outputs": [],
   "source": [
    "plot_bivariate_data <- function(df, x, y) {\n",
    "    px <- df[[x]]\n",
    "    py <- df[[y]]\n",
    "    titlex <- str_to_title(gsub(\"_\", \" \", x))\n",
    "    titley <- str_to_title(gsub(\"_\", \" \", y))\n",
    "    title = paste(c(titlex, \"and\", titley), collapse = \" \")\n",
    "\n",
    "    ggplot(\n",
    "        data=df,\n",
    "        mapping=aes(x=px, y=py)\n",
    "    ) + \n",
    "        geom_point(aes(color=sex, shape=sex)) +\n",
    "        geom_smooth() +\n",
    "        labs(\n",
    "            title=title,\n",
    "            x=titlex,\n",
    "            y=titley,\n",
    "            color=\"Sex\",\n",
    "            shape=\"Sex\"\n",
    "        )\n",
    "}"
   ]
  },
