   "source": [
    "numeric_cols <- df %>% select(where(is.numeric))\n",
    "categorical_cols <- df %>% select(where(is.character))\n",
    "\n",
    "min_max_scaler <- preProcess(numeric_cols, method=c(\"range\"))\n",
    "numeric_cols <- predict(min_max_scaler, numeric_cols)\n",
    "\n",
    "ohe_encoder <- dummyVars(categorical_cols, data=categorical_cols)\n",
    "categorical_cols <- predict(ohe_encoder, categorical_cols)\n",
    "\n",
    "preprocessed_df <- cbind(categorical_cols, numeric_cols)\n",
    "head(preprocessed_df)"
   ]
  },
