   "source": [
    "fitControl <- trainControl(method=\"repeatedcv\", number=5,repeats=5)\n",
    "\n",
    "train_and_predict <- function(y, train_set, test_set, method, control) {\n",
    "    x <- train_set[,!(names(train_set) %in% c(y))]\n",
    "    y <- train_set[[y]]\n",
    "\n",
    "    fit <- train(\n",
    "        x=x,\n",
    "        y=y,\n",
    "        method=method,\n",
    "        trControl=control\n",
    "    )\n",
    "    preds <- predict(fit, newdata=test_set)\n",
    "    return (preds)\n",
    "}\n",
    "\n",
    "lm_preds <- train_and_predict(\"shell_length\", training, testing, \"lm\", fitControl)\n",
    "lm_preds"
   ]
  },
